// ── Pull original webhook body ──────────────────────────────
const webhookBody = $('Webhook - Study Planner').item.json.body
                 || $('Webhook - Study Planner').item.json;

// ── Extract RAG chunks from backend search result ───────────
const result = $input.first().json;
const chunks = result.data || result.matches || result.results || [];

let curriculumContext = '';
if (Array.isArray(chunks) && chunks.length > 0) {
  curriculumContext = chunks
    .map((item, i) => `[${i + 1}] ${item.chunkText || item.text || item.content || ''}`)
    .join('\n\n');
} else {
  curriculumContext = 'No matching curriculum context found in Google Drive.';
}

// ── Return merged body – curriculumContext now populated ─────
return [{ json: { ...webhookBody, curriculumContext, ragChunksFound: chunks.length, ragInjected: true } }];

// body arrives with curriculumContext already injected by the RAG pipeline
const body = $input.item.json;

const prompt = `
You are Learnify Study Planner.

Create a practical, curriculum-aligned study plan for a student.

Subject: ${body.subject}
Topic: ${body.topic}
Exam Date: ${body.examDate}
Available Hours Per Day: ${body.availableHoursPerDay}

Curriculum Context (Retrieved from Google Drive RAG – prioritise this):
${body.curriculumContext || 'No curriculum context available.'}

Scanned Note:
${body.extractedText || 'No scanned note provided.'}

Return valid JSON only in this format:
{
  "studentId": "${body.studentId}",
  "noteId": "${body.noteId}",
  "examDate": "${body.examDate}",
  "availableHoursPerDay": ${Number(body.availableHoursPerDay || 1)},
  "ragChunksUsed": ${body.ragChunksFound || 0},
  "plan": [
    { "day": "Day 1", "subject": "${body.subject}", "topic": "${body.topic}", "durationMinutes": 30, "task": "Study key concept and answer practice questions" }
  ]
}

Rules:
- Create 7 days of study tasks.
- Prioritise topics and subtopics from the Curriculum Context.
- Include revision days and timed practice sessions.
- Align content with WAEC/NECO/JAMB exam requirements.
- Do not include markdown.
`;
return [{ json: { ...body, prompt } }];

const response = $input.first().json;
let text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
text = text.replace(/```json/g, '').replace(/```/g, '').trim();
let parsed;
try { parsed = JSON.parse(text); } catch (error) { throw new Error('Gemini did not return valid study plan JSON: ' + text); }
return [{ json: parsed }];
